package com.bank.surrogate;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.logging.Logger;

public class CustomerDao {
    private static final Logger log = Logger.getLogger(CustomerDao.class.getName());
    private final Connection conn;

    public CustomerDao(Connection conn) { this.conn = conn; }

    // Update a NATURAL attribute (PAN). Because PAN is NOT the primary key,
    // this touches exactly one column in one row — no child FK changes needed.
    public void correctPan(long customerId, String newPan) throws Exception {
        try (PreparedStatement ps = conn.prepareStatement(
                "UPDATE customers SET pan = ? WHERE customer_id = ?")) {
            ps.setString(1, newPan);
            ps.setLong(2, customerId);
            int rows = ps.executeUpdate();
            log.info(() -> "Corrected PAN for customer " + customerId + " (" + rows + " row). "
                + "Surrogate id and all account references unchanged.");
        }
    }

    public long findIdByEmail(String email) throws Exception {
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT customer_id FROM customers WHERE email = ?")) {
            ps.setString(1, email);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? rs.getLong(1) : -1L;
            }
        }
    }
}
