                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            CustomerDao dao = new CustomerDao(conn);

            long rajeshId = dao.findIdByEmail("rajesh@example.com");  // surrogate id
            log.info(() -> "Rajesh surrogate customer_id = " + rajeshId);

            // Government reissues Rajesh's PAN — only ONE row changes.
            dao.correctPan(rajeshId, "ABCDE9999Z");

            log.info("Surrogate PK stayed stable; PAN/email remain unique alternate keys.");
        }
    }
}
